import{f as r,o as i,c as o,ah as t}from"./chunks/framework.5bt9HFMa.js";const d=JSON.parse('{"title":"操作系统 I/O 管理","description":"","frontmatter":{},"headers":[],"relativePath":"series/操作系统/05-IO.md","filePath":"series/操作系统/05-IO.md","lastUpdated":1777791679000}'),n={name:"series/操作系统/05-IO.md"};function e(a,l,s,g,h,u){return i(),o("div",null,l[0]||(l[0]=[t('<h1 id="操作系统-i-o-管理" tabindex="-1">操作系统 I/O 管理 <a class="header-anchor" href="#操作系统-i-o-管理" aria-label="Permalink to &quot;操作系统 I/O 管理&quot;">​</a></h1><p>I/O 管理是操作系统中最庞杂的部分，负责管理各种外部设备，向用户提供统一、易用的接口，并提高设备利用率和系统并行度。</p><hr><h2 id="一、i-o-设备与控制器" tabindex="-1">一、I/O 设备与控制器 <a class="header-anchor" href="#一、i-o-设备与控制器" aria-label="Permalink to &quot;一、I/O 设备与控制器&quot;">​</a></h2><h3 id="_1-设备分类" tabindex="-1">1. 设备分类 <a class="header-anchor" href="#_1-设备分类" aria-label="Permalink to &quot;1. 设备分类&quot;">​</a></h3><ul><li><strong>按传输速率</strong>：低速（键盘鼠标）、中速（打印机）、高速（磁盘）。</li><li><strong>按信息交换单位</strong>： <ul><li><strong>块设备 (Block Device)</strong>：以数据块为单位存储/传输，可寻址（如磁盘）。</li><li><strong>字符设备 (Character Device)</strong>：以字符为单位，不可寻址（如键盘、串口）。</li></ul></li><li><strong>按共享属性</strong>： <ul><li><strong>独占设备</strong>：一次只能分配给一个进程（如打印机）。</li><li><strong>共享设备</strong>：可同时分配给多个进程（如磁盘）。</li><li><strong>虚拟设备</strong>：通过 SPOOLing 技术将独占设备模拟为共享设备。</li></ul></li></ul><h3 id="_2-i-o-控制器-device-controller" tabindex="-1">2. I/O 控制器 (Device Controller) <a class="header-anchor" href="#_2-i-o-控制器-device-controller" aria-label="Permalink to &quot;2. I/O 控制器 (Device Controller)&quot;">​</a></h3><p>CPU 无法直接控制机械设备，需通过控制器。</p><ul><li><strong>功能</strong>：接收 CPU 命令、地址识别、数据交换、设备状态报告。</li><li><strong>组成</strong>：寄存器（数据/状态/控制）、控制逻辑。</li></ul><hr><h2 id="二、i-o-控制方式" tabindex="-1">二、I/O 控制方式 <a class="header-anchor" href="#二、i-o-控制方式" aria-label="Permalink to &quot;二、I/O 控制方式&quot;">​</a></h2><p>随着技术发展，CPU 干预越来越少，I/O 效率越来越高。</p><h3 id="_1-程序直接控制-polling" tabindex="-1">1. 程序直接控制 (Polling) <a class="header-anchor" href="#_1-程序直接控制-polling" aria-label="Permalink to &quot;1. 程序直接控制 (Polling)&quot;">​</a></h3><ul><li>CPU 循环轮询检查设备状态。</li><li><strong>缺点</strong>：CPU 忙等，利用率极低。</li></ul><h3 id="_2-中断驱动方式-interrupt-driven" tabindex="-1">2. 中断驱动方式 (Interrupt-driven) <a class="header-anchor" href="#_2-中断驱动方式-interrupt-driven" aria-label="Permalink to &quot;2. 中断驱动方式 (Interrupt-driven)&quot;">​</a></h3><ul><li>I/O 完成时发中断通知 CPU。</li><li><strong>优点</strong>：CPU 和 I/O 可并行。</li><li><strong>缺点</strong>：每个字/字节都要中断，频繁中断消耗 CPU。</li></ul><h3 id="_3-dma-方式-direct-memory-access" tabindex="-1">3. DMA 方式 (Direct Memory Access) <a class="header-anchor" href="#_3-dma-方式-direct-memory-access" aria-label="Permalink to &quot;3. DMA 方式 (Direct Memory Access)&quot;">​</a></h3><ul><li>专门的 DMA 控制器负责数据传输。</li><li><strong>特点</strong>： <ul><li>数据传输单位是<strong>块</strong>。</li><li>数据直接在<strong>内存和设备</strong>间传输，不经过 CPU。</li><li>仅在传送开始和结束时才需 CPU 干预。</li></ul></li><li><strong>优点</strong>：进一步解放 CPU。</li></ul><h3 id="_4-通道控制方式-channel" tabindex="-1">4. 通道控制方式 (Channel) <a class="header-anchor" href="#_4-通道控制方式-channel" aria-label="Permalink to &quot;4. 通道控制方式 (Channel)&quot;">​</a></h3><ul><li>专门的 I/O 处理器（通道），有自己的指令集。</li><li>可以控制多台设备，执行复杂的 I/O 程序。</li></ul><hr><h2 id="三、i-o-软件层次结构" tabindex="-1">三、I/O 软件层次结构 <a class="header-anchor" href="#三、i-o-软件层次结构" aria-label="Permalink to &quot;三、I/O 软件层次结构&quot;">​</a></h2><p>从上到下依次为：</p><ol><li><strong>用户层 I/O 软件</strong>：库函数（如 <code>printf</code>, <code>scanf</code>），系统调用接口。</li><li><strong>设备独立性软件 (Device Independent Software)</strong>： <ul><li>执行所有设备公有的操作。</li><li><strong>逻辑设备名到物理设备名的映射</strong> (LUT)。</li><li><strong>设备保护</strong>。</li><li><strong>缓冲管理</strong>。</li><li><strong>差错处理</strong>。</li></ul></li><li><strong>设备驱动程序 (Device Driver)</strong>： <ul><li>与硬件直接相关，每类设备对应一个驱动。</li><li>将逻辑命令转换为物理操作（设置寄存器）。</li></ul></li><li><strong>中断处理程序</strong>： <ul><li>处理 I/O 完成后的中断信号。</li></ul></li></ol><hr><h2 id="四、核心-i-o-技术" tabindex="-1">四、核心 I/O 技术 <a class="header-anchor" href="#四、核心-i-o-技术" aria-label="Permalink to &quot;四、核心 I/O 技术&quot;">​</a></h2><h3 id="_1-缓冲技术-buffering" tabindex="-1">1. 缓冲技术 (Buffering) <a class="header-anchor" href="#_1-缓冲技术-buffering" aria-label="Permalink to &quot;1. 缓冲技术 (Buffering)&quot;">​</a></h3><p>目的：缓和 CPU 与 I/O 设备速度不匹配的矛盾，减少 CPU 中断频率。</p><ul><li><strong>单缓冲</strong>：处理时间 $Max(C, T) + M$。</li><li><strong>双缓冲</strong>：处理时间 $Max(C, T)$。</li><li><strong>循环缓冲</strong>：多个缓冲区组成圆环。</li><li><strong>缓冲池 (Buffer Pool)</strong>：系统公用的缓冲区集合，包含空缓冲队列、输入队列、输出队列。</li></ul><h3 id="_2-设备分配" tabindex="-1">2. 设备分配 <a class="header-anchor" href="#_2-设备分配" aria-label="Permalink to &quot;2. 设备分配&quot;">​</a></h3><ul><li><strong>数据结构</strong>： <ul><li><strong>SDT</strong> (系统设备表)：整个系统一张。</li><li><strong>DCT</strong> (设备控制表)：每个设备一张。</li><li><strong>COCT</strong> (控制器控制表)。</li><li><strong>CHCT</strong> (通道控制表)。</li></ul></li><li><strong>分配原则</strong>：安全性（避免死锁）、灵活性。</li></ul><h3 id="_3-spooling-技术-假脱机" tabindex="-1">3. SPOOLing 技术 (假脱机) <a class="header-anchor" href="#_3-spooling-技术-假脱机" aria-label="Permalink to &quot;3. SPOOLing 技术 (假脱机)&quot;">​</a></h3><p><strong>Simultaneous Peripheral Operations On-Line</strong> (外部设备联机并行操作)。</p><ul><li><strong>原理</strong>：利用磁盘空间模拟独占设备。</li><li><strong>组成</strong>： <ul><li><strong>输入井/输出井</strong>：磁盘上的区域。</li><li><strong>输入进程/输出进程</strong>：负责模拟外围机。</li><li><strong>输入缓冲区/输出缓冲区</strong>：内存中的区域。</li></ul></li><li><strong>应用</strong>：<strong>共享打印机</strong>。将打印请求挂到队列，由守护进程依次打印，用户进程无需等待。</li><li><strong>意义</strong>：将<strong>独占设备</strong>改造为<strong>共享设备</strong>（虚拟设备）。</li></ul><hr><blockquote><p><strong>总结</strong></p><ul><li><strong>控制方式进化</strong>：轮询 → 中断 → DMA → 通道。</li><li><strong>软件分层</strong>：独立性软件屏蔽了硬件差异，驱动程序负责具体硬件。</li><li><strong>SPOOLing</strong>：是实现虚拟设备的关键技术，极大提高了独占设备的利用率。</li></ul></blockquote>',36)]))}const P=r(n,[["render",e]]);export{d as __pageData,P as default};
